const items = $input.all();

const resultado = [];

for (const item of items) {
  // Projetos expandidos relacionados à tarefa
  const projetos = item.json["🎯 Projetos"] ?? [];

  for (const projeto of projetos) {
    // Taxonomias expandidas relacionadas ao projeto
    const taxonomias = projeto["🏷️ Taxonomia"] ?? [];

    // Verifica se alguma taxonomia é "Post"
    const temPost = taxonomias.some(taxonomia => {
      const nome =
        taxonomia.properties?.["Name"]?.title?.[0]?.plain_text;

      return nome?.toLowerCase() === "post";
    });

    if (temPost) {
      resultado.push({
        json: projeto
      });
    }
  }
}

return resultado;

const items = $input.all();

const conhecimentosFiltrados = [];

for (const item of items) {
  // Conhecimentos expandidos relacionados ao projeto
  const conhecimentos = item.json["📚 Conhecimentos"] ?? [];

  for (const conhecimento of conhecimentos) {
    // Taxonomias expandidas relacionadas ao conhecimento
    const taxonomias = conhecimento["🏷️ Taxonomias"] ?? [];

    // Verifica se possui a taxonomia "Assunto"
    const temTaxonomiaAssunto = taxonomias.some(taxonomia => {
      const nome =
        taxonomia.properties?.["Name"]?.title?.[0]?.plain_text;

      return nome?.toLowerCase() === "assunto";
    });

    if (temTaxonomiaAssunto) {
      conhecimentosFiltrados.push(conhecimento);
    }
  }
}

return [
  {
    json: {
      conhecimentos: conhecimentosFiltrados.flat()
    }
  }
];

const items = $input.all();

function getTitle(page) {
  const title =
    page?.properties?.Name?.title ??
    page?.properties?.Nome?.title;

  if (!Array.isArray(title)) return null;

  return title
    .map(item => item?.plain_text ?? '')
    .join('')
    .trim();
}

function hasTaxonomy(page, taxonomyName) {
  const taxonomies = page?.['🏷️ Taxonomias'];

  if (!Array.isArray(taxonomies)) {
    return false;
  }

  return taxonomies.some(taxonomy =>
    getTitle(taxonomy)?.toLowerCase() === taxonomyName.toLowerCase()
  );
}

function annotationIsValid(annotation) {
  // A mesma anotação precisa ser Post + LinkedIn
  if (!hasTaxonomy(annotation, 'Post')) {
    return false;
  }

  if (!hasTaxonomy(annotation, 'LinkedIn')) {
    return false;
  }

  // Resultados precisa estar expandido
  const results = annotation?.['📦 Resultados'];

  if (!Array.isArray(results)) {
    return false;
  }

  // E ainda não pode possuir resultado
  return results.length === 0;
}

function findValidAnnotation(knowledge) {
  const annotations = knowledge?.['📝 Anotações'];

  if (!Array.isArray(annotations)) {
    return null;
  }

  return annotations.find(annotationIsValid) ?? null;
}

function findFirstValidKnowledge(knowledge) {
  // O próprio conhecimento precisa ser um Assunto
  if (hasTaxonomy(knowledge, 'Assunto')) {
    const annotation = findValidAnnotation(knowledge);

    if (annotation) {
      return {
        knowledge,
        annotation
      };
    }
  }

  // Se não servir, procura nos filhos
  const children = knowledge?.Subitem;

  if (Array.isArray(children)) {
    for (const child of children) {
      const found = findFirstValidKnowledge(child);

      if (found) {
        return found;
      }
    }
  }

  return null;
}

for (const item of items) {
  const found = findFirstValidKnowledge(item.json);

  if (found) {
    return [
      {
        json: {
          "📚 Conhecimentos": [
            {
              id: found.knowledge.id,
              nome: getTitle(found.knowledge)
            }
          ],
          "📝 Anotação": [
            {
              id: found.annotation.id,
              nome: getTitle(found.annotation)
            }
          ]
        }
      }
    ];
  }
}

return [
  {
    json: {
      "📚 Conhecimentos": [],
      "📝 Anotação": []
    }
  }
];

